#!/usr/bin/env bash
# Prints the Homebrew formula for an mvm release (implementation plan 0.3b).
# Usage: formula.sh <version> <dist dir holding the release archives>
set -euo pipefail
version="$1"; dist="$2"
base="https://github.com/benallfree/mvm/releases/download/mvm-v$version"
sum() { sha256sum "$dist/mvm-$version-$1.tar.gz" | cut -d' ' -f1; }
cat <<RUBY
# Generated by packaging/homebrew/formula.sh in benallfree/mvm; do not edit.
class Mvm < Formula
  desc "MVM command-line tool: build applets, run simulated meshes, manage nodes"
  homepage "https://github.com/benallfree/mvm"
  version "$version"
  license "MIT"

  on_macos do
    on_arm do
      url "$base/mvm-$version-aarch64-apple-darwin.tar.gz"
      sha256 "$(sum aarch64-apple-darwin)"
    end
    on_intel do
      url "$base/mvm-$version-x86_64-apple-darwin.tar.gz"
      sha256 "$(sum x86_64-apple-darwin)"
    end
  end

  on_linux do
    on_arm do
      url "$base/mvm-$version-aarch64-unknown-linux-gnu.tar.gz"
      sha256 "$(sum aarch64-unknown-linux-gnu)"
    end
    on_intel do
      url "$base/mvm-$version-x86_64-unknown-linux-gnu.tar.gz"
      sha256 "$(sum x86_64-unknown-linux-gnu)"
    end
  end

  def install
    bin.install "mvm"
  end

  test do
    assert_equal "mvm #{version}", shell_output("#{bin}/mvm --version").strip
  end
end
RUBY
